method MergeSorted(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
{
  out := [];
  var i := 0;
  var j := 0;
  while i < |a| || j < |b|
    invariant 0 <= i <= |a|
    invariant 0 <= j <= |b|
    invariant Sorted(out)
    invariant multiset(out) == multiset(a[..i]) + multiset(b[..j])
    invariant forall k :: 0 <= k < |out| ==> (i < |a| ==> out[k] <= a[i])
    invariant forall k :: 0 <= k < |out| ==> (j < |b| ==> out[k] <= b[j])
    decreases |a| - i + |b| - j
  {
    if j == |b| || (i < |a| && a[i] <= b[j]) {
      var x := a[i];
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      var newOut := out + [x];
      assert forall k :: 0 <= k < |newOut| ==> newOut[k] <= x;
      assert Sorted(newOut);
      assert a[..i+1] == a[..i] + [a[i]];
      if i + 1 < |a| {
        assert a[i] <= a[i+1];
      }
      out := newOut;
      i := i + 1;
    } else {
      var x := b[j];
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      var newOut := out + [x];
      assert forall k :: 0 <= k < |newOut| ==> newOut[k] <= x;
      assert Sorted(newOut);
      assert b[..j+1] == b[..j] + [b[j]];
      if j + 1 < |b| {
        assert b[j] <= b[j+1];
      }
      out := newOut;
      j := j + 1;
    }
  }
  assert a[..i] == a;
  assert b[..j] == b;
}

