lemma MergeSorted_IndexOrder(s: seq<int>, i: int, j: int)
  requires Sorted(s)
  requires 0 <= i <= j < |s|
  ensures s[i] <= s[j]
{
  if i < j {
    assert s[i] <= s[j];
  }
}

lemma MergeSorted_AppendSorted(s: seq<int>, x: int)
  requires Sorted(s)
  requires |s| == 0 || s[|s| - 1] <= x
  ensures Sorted(s + [x])
{
  forall i, j | 0 <= i < j < |s + [x]|
    ensures (s + [x])[i] <= (s + [x])[j]
  {
    if j < |s| {
      MergeSorted_IndexOrder(s, i, j);
      assert (s + [x])[i] == s[i];
      assert (s + [x])[j] == s[j];
    } else {
      assert j == |s|;
      assert i < |s|;
      MergeSorted_IndexOrder(s, i, |s| - 1);
      assert (s + [x])[i] == s[i];
      assert (s + [x])[j] == x;
    }
  }
}

lemma MergeSorted_PrefixStep(s: seq<int>, i: int)
  requires 0 <= i < |s|
  ensures s[..i + 1] == s[..i] + [s[i]]
{
  assert s[..i] + s[i..i + 1] == s[..i + 1];
  assert s[i..i + 1] == [s[i]];
}

method MergeSorted(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
{
  var i := 0;
  var j := 0;
  out := [];

  while i < |a| || j < |b|
    invariant 0 <= i <= |a|
    invariant 0 <= j <= |b|
    invariant Sorted(out)
    invariant multiset(out) ==
              multiset(a[..i]) + multiset(b[..j])
    invariant |out| > 0 ==>
              (forall k :: i <= k < |a| ==>
                 out[|out| - 1] <= a[k])
    invariant |out| > 0 ==>
              (forall k :: j <= k < |b| ==>
                 out[|out| - 1] <= b[k])
    decreases |a| - i + |b| - j
  {
    if j == |b| || (i < |a| && a[i] <= b[j]) {
      assert i < |a|;

      var oldOut := out;
      var oldI := i;
      var x := a[oldI];

      assert multiset(oldOut) ==
             multiset(a[..oldI]) + multiset(b[..j]);

      if |oldOut| > 0 {
        assert oldOut[|oldOut| - 1] <= a[oldI];
      }
      MergeSorted_AppendSorted(oldOut, x);

      MergeSorted_PrefixStep(a, oldI);
      assert multiset(a[..oldI + 1]) ==
             multiset(a[..oldI]) + multiset([x]);

      out := oldOut + [x];
      i := oldI + 1;

      calc {
        multiset(out);
        == multiset(oldOut) + multiset([x]);
        == (multiset(a[..oldI]) + multiset(b[..j]))
           + multiset([x]);
        == multiset(a[..oldI + 1]) + multiset(b[..j]);
        == multiset(a[..i]) + multiset(b[..j]);
      }

      assert out[|out| - 1] == x;

      forall k | i <= k < |a|
        ensures out[|out| - 1] <= a[k]
      {
        assert oldI < k;
        MergeSorted_IndexOrder(a, oldI, k);
      }

      forall k | j <= k < |b|
        ensures out[|out| - 1] <= b[k]
      {
        assert j < |b|;
        assert x <= b[j];
        MergeSorted_IndexOrder(b, j, k);
      }
    } else {
      assert j < |b|;

      var oldOut := out;
      var oldJ := j;
      var x := b[oldJ];

      assert multiset(oldOut) ==
             multiset(a[..i]) + multiset(b[..oldJ]);

      if |oldOut| > 0 {
        assert oldOut[|oldOut| - 1] <= b[oldJ];
      }
      MergeSorted_AppendSorted(oldOut, x);

      MergeSorted_PrefixStep(b, oldJ);
      assert multiset(b[..oldJ + 1]) ==
             multiset(b[..oldJ]) + multiset([x]);

      out := oldOut + [x];
      j := oldJ + 1;

      calc {
        multiset(out);
        == multiset(oldOut) + multiset([x]);
        == (multiset(a[..i]) + multiset(b[..oldJ]))
           + multiset([x]);
        == multiset(a[..i]) + multiset(b[..oldJ + 1]);
        == multiset(a[..i]) + multiset(b[..j]);
      }

      assert out[|out| - 1] == x;

      forall k | j <= k < |b|
        ensures out[|out| - 1] <= b[k]
      {
        assert oldJ < k;
        MergeSorted_IndexOrder(b, oldJ, k);
      }

      forall k | i <= k < |a|
        ensures out[|out| - 1] <= a[k]
      {
        assert i < |a|;
        assert x <= a[i];
        MergeSorted_IndexOrder(a, i, k);
      }
    }
  }

  assert i == |a|;
  assert j == |b|;
  assert a[..i] == a;
  assert b[..j] == b;
}

